		assertSame(connectionFailure, assertThrows(RuntimeException.class, fixture::tearDown));
		assertArrayEquals(new Throwable[] { shutdownFailure }, connectionFailure.getSuppressed());
		verify(repository).shutDown();
		assertFalse(Files.exists(directory), "later cleanup must run even when both earlier closes fail");
